public class Main {
    public static void main(String[] args) {
        TaiKhoan tk = new TaiKhoan();
        tk.napTien(500);
        tk.napTien(300);
        System.out.println(tk.getSoDu());
    }
}

class TaiKhoan {
    private double soDu = 0;
    void napTien(double t) {
        if (t > 0) soDu += t;
    }
    double getSoDu() { return soDu; }
}
